INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload)
SELECT 'core-2026-09-v4','future-forms','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"future-forms","title":"Future plans, predictions and arrangements","level":"A2","order":28,"summary":"Choose a future form by the speaker’s intention: a decision, a plan, an arrangement or a timetable.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Decisions and promises","Prior intentions","Arranged future events","Timetables and future time clauses"],"rules":[{"title":"Decisions and promises","explanation":"Use **will + base verb** for a decision made while speaking, a promise or a prediction. Will does not change with the subject. A time word such as tomorrow does not force will: the speaker’s meaning matters more than the date. In conversation, I will often becomes I’ll.","pattern":"I **will help**. / She **will not help**.","commonMistakes":["Do not add -s after will: she will helps is not the standard form."],"examples":["Make a promise with will: I **will prepare** the visitor guide tomorrow.","Make a promise with will: I **will restore** the old portrait tomorrow."],"skill":"form"},{"title":"Prior intentions","explanation":"Use **be going to + base verb** for an intention formed before speaking. The form of be agrees with the subject. Going to also introduces a prediction based on present evidence. A dark sky can justify It is going to rain, even if no one planned the rain.","pattern":"We **are going to leave**.","commonMistakes":["Going to and will can overlap. These questions explicitly name the construction rather than treating both as universally incompatible."],"examples":["Complete the prior plan using going to: We **are going to prepare** the visitor guide next week.","Complete the prior plan using going to: We **are going to restore** the old portrait next week."],"skill":"meaning"},{"title":"Arranged future events","explanation":"The present continuous can describe a future arrangement, especially when another person, place or booking is involved. A future time expression separates this use from an action happening now. Present continuous is not a general replacement for will in predictions.","pattern":"We **are meeting** the guide tomorrow.","commonMistakes":["It is raining tomorrow is unusual as a simple weather prediction; use a suitable prediction form."],"examples":["Use the present continuous for a booked arrangement: She **is preparing** the visitor guide on Tuesday.","Use the present continuous for a booked arrangement: She **is restoring** the old portrait on Tuesday."],"skill":"contrast"},{"title":"Timetables and future time clauses","explanation":"Use present simple for published timetables. After when, as soon as, before and until in an ordinary future time clause, use a present form. The main clause can contain will. This rule concerns time clauses, not indirect questions about what will happen.","pattern":"I’ll call **when I arrive**.","commonMistakes":["I wonder when she will arrive is an indirect question, so will is possible there."],"examples":["Keep the when-clause in the present simple: I will call when I **prepare** the visitor guide.","Keep the when-clause in the present simple: I will call when I **restore** the old portrait."],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-future-forms"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"chapter":{"introduction":["Choose a future form by the speaker’s intention: a decision, a plan, an arrangement or a timetable.","The form tells you how to build the sentence; the context tells you why that form is useful. Read each section with both questions in mind. The examples make one contrast at a time, while the practice mixes the skills so that you learn to recognise the pattern yourself."],"rules":[{"title":"Decisions and promises","explanation":"Use **will + base verb** for a decision made while speaking, a promise or a prediction. Will does not change with the subject. A time word such as tomorrow does not force will: the speaker’s meaning matters more than the date. In conversation, I will often becomes I’ll.","pattern":"I **will help**. / She **will not help**.","commonMistakes":["Do not add -s after will: she will helps is not the standard form."],"examples":["Make a promise with will: I **will prepare** the visitor guide tomorrow.","Make a promise with will: I **will restore** the old portrait tomorrow."],"skill":"form","id":"future-forms-foundation-1","domain":"verbs","referenceIds":["bc-future-forms"],"readingVersion":"core-2026-09-v3"},{"title":"Prior intentions","explanation":"Use **be going to + base verb** for an intention formed before speaking. The form of be agrees with the subject. Going to also introduces a prediction based on present evidence. A dark sky can justify It is going to rain, even if no one planned the rain.","pattern":"We **are going to leave**.","commonMistakes":["Going to and will can overlap. These questions explicitly name the construction rather than treating both as universally incompatible."],"examples":["Complete the prior plan using going to: We **are going to prepare** the visitor guide next week.","Complete the prior plan using going to: We **are going to restore** the old portrait next week."],"skill":"meaning","id":"future-forms-foundation-2","domain":"verbs","referenceIds":["bc-future-forms"],"readingVersion":"core-2026-09-v3"},{"title":"Arranged future events","explanation":"The present continuous can describe a future arrangement, especially when another person, place or booking is involved. A future time expression separates this use from an action happening now. Present continuous is not a general replacement for will in predictions.","pattern":"We **are meeting** the guide tomorrow.","commonMistakes":["It is raining tomorrow is unusual as a simple weather prediction; use a suitable prediction form."],"examples":["Use the present continuous for a booked arrangement: She **is preparing** the visitor guide on Tuesday.","Use the present continuous for a booked arrangement: She **is restoring** the old portrait on Tuesday."],"skill":"contrast","id":"future-forms-foundation-3","domain":"verbs","referenceIds":["bc-future-forms"],"readingVersion":"core-2026-09-v3"},{"title":"Timetables and future time clauses","explanation":"Use present simple for published timetables. After when, as soon as, before and until in an ordinary future time clause, use a present form. The main clause can contain will. This rule concerns time clauses, not indirect questions about what will happen.","pattern":"I’ll call **when I arrive**.","commonMistakes":["I wonder when she will arrive is an indirect question, so will is possible there."],"examples":["Keep the when-clause in the present simple: I will call when I **prepare** the visitor guide.","Keep the when-clause in the present simple: I will call when I **restore** the old portrait."],"skill":"application","id":"future-forms-foundation-4","domain":"verbs","referenceIds":["bc-future-forms"],"readingVersion":"core-2026-09-v3"},{"domain":"verbs","id":"future-in-the-past","title":"Future in the past: would and was going to","explanation":"A future viewed from a past point often uses would or was/were going to. The event may or may not later happen; context tells you whether the plan was fulfilled. Was about to can describe an imminent past event. Distinguish predictive would from conditional, habitual and polite uses of the same modal.","pattern":"She said she **would call**.","examples":["We **were going to leave**, but the car would not start.","I **was about to speak** when the phone rang."],"commonMistakes":["Was going to does not itself guarantee cancellation: We were going to meet at six, and we did is possible."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"verbs","id":"future-periphrases","title":"Be about to, be due to, be to and likely to","explanation":"Future-oriented expressions add meanings beyond time. Be about to signals imminence; be due to refers to an expectation or schedule. Be to can express an official arrangement or instruction. Be likely to expresses probability. Choose the construction that matches the event’s status and the speaker’s stance.","pattern":"The train **is due to arrive** at six.","examples":["The film **is about to begin**.","Visitors **are to remain** behind the barrier."],"commonMistakes":["Be about to normally describes the immediate future, so it is unsuitable for a distant plan without a shifted viewpoint. Due to + noun can instead mean because of."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"}],"recap":["I **will help**. / She **will not help**.","We **are going to leave**.","We **are meeting** the guide tomorrow.","I’ll call **when I arrive**."],"readingVersion":"core-2026-09-v4"},"stage":"3 · Time and experience","prerequisites":["past-continuous"],"readingReferenceIds":["bc-future-forms","cambridge-comprehensive-scope"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='future-forms'
